\timing on
SELECT count(*) AS mints_do_minuto FROM unnest(ARRAY(SELECT mint FROM meme_features_1m WHERE features_version = 'meme_features_v3' AND end_time = TIMESTAMPTZ '2026-10-01 03:25:00+00'));
\echo ===== ANTES (_PEDIGREE, leitura completa)
EXPLAIN (ANALYZE, BUFFERS, TIMING OFF, SUMMARY ON) SELECT t.mint,        CASE WHEN t.creator IS NULL OR t.created_at IS NULL THEN NULL ELSE (         SELECT count(*) FROM meme_tokens o WHERE o.creator = t.creator            AND o.mint <> t.mint AND o.created_at IS NOT NULL            AND o.created_at <= t.created_at            AND o.created_at > t.created_at - make_interval(secs => 3600)       ) END AS creator_prior_mints_1h,        CASE WHEN t.symbol IS NULL OR t.created_at IS NULL THEN NULL ELSE (         SELECT count(*) FROM meme_tokens o WHERE o.symbol = t.symbol            AND o.mint <> t.mint AND o.created_at IS NOT NULL            AND o.created_at <= t.created_at            AND o.created_at > t.created_at - make_interval(secs => 86400)       ) END AS symbol_dup_24h,        CASE WHEN t.creator IS NULL OR t.created_at IS NULL THEN NULL ELSE (        SELECT count(*) FROM meme_tokens o WHERE o.creator = t.creator   AND o.mint <> t.mint AND o.created_at IS NOT NULL AND o.created_at <= t.created_at   AND o.created_at > t.created_at - make_interval(secs => 604800)           AND (             EXISTS (SELECT 1 FROM meme_features_1m pf WHERE pf.mint = o.mint                        AND pf.creator_sold = true AND pf.end_time < t.created_at)             OR EXISTS (SELECT 1 FROM meme_paper_bets pb WHERE pb.mint = o.mint                           AND pb.rule_set_id <> '01994d00-6c1a-7000-8000-00000000001c'::uuid                           AND pb.rule_set_id <> '01994d00-6c1a-7000-8000-00000000001d'::uuid                           AND pb.rule_set_id <> '01994d00-6c1a-7000-8000-00000000001e'::uuid                           AND pb.rule_set_id <> ALL(ARRAY['01994d00-6c1a-7000-8000-00000000001f','01994d00-6c1a-7000-8000-000000000020','01994d00-6c1a-7000-8000-000000000021']::uuid[])                           AND pb.creator_sold_seen_at IS NOT NULL                           AND pb.creator_sold_seen_at < t.created_at)             OR EXISTS (SELECT 1 FROM meme_paper_bets pb2 WHERE pb2.mint = o.mint                           AND pb2.rule_set_id <> '01994d00-6c1a-7000-8000-00000000001c'::uuid                           AND pb2.rule_set_id <> '01994d00-6c1a-7000-8000-00000000001d'::uuid                           AND pb2.rule_set_id <> '01994d00-6c1a-7000-8000-00000000001e'::uuid                           AND pb2.rule_set_id <> ALL(ARRAY['01994d00-6c1a-7000-8000-00000000001f','01994d00-6c1a-7000-8000-000000000020','01994d00-6c1a-7000-8000-000000000021']::uuid[])                           AND pb2.exit ->> 'reason' = 'creator_dump'                           AND pb2.exit_at < t.created_at)           )       ) END AS creator_prior_dump_count,        CASE WHEN t.creator IS NULL OR t.created_at IS NULL THEN NULL ELSE (        SELECT count(*) FROM meme_tokens o WHERE o.creator = t.creator   AND o.mint <> t.mint AND o.created_at IS NOT NULL AND o.created_at <= t.created_at   AND o.created_at > t.created_at - make_interval(secs => 604800)           AND EXISTS (             SELECT 1 FROM (               SELECT max(w.mcap_sol) AS peak, min(w.mcap_sol) AS trough                FROM meme_features_1m w WHERE w.mint = o.mint AND w.mcap_sol IS NOT NULL                  AND w.end_time > o.created_at                  AND w.end_time <= o.created_at + interval '30 minutes'             ) window_30m              WHERE window_30m.peak IS NOT NULL AND window_30m.peak > 0                AND window_30m.trough < window_30m.peak * 0.2           )       ) END AS creator_prior_dead_count FROM meme_tokens t WHERE t.mint = ANY(ARRAY(SELECT mint FROM meme_features_1m WHERE features_version = 'meme_features_v3' AND end_time = TIMESTAMPTZ '2026-10-01 03:25:00+00'));
\echo ===== DEPOIS (_PEDIGREE_COUNTS, so as duas contagens)
EXPLAIN (ANALYZE, BUFFERS, TIMING OFF, SUMMARY ON) SELECT t.mint,        CASE WHEN t.creator IS NULL OR t.created_at IS NULL THEN NULL ELSE (         SELECT count(*) FROM meme_tokens o WHERE o.creator = t.creator            AND o.mint <> t.mint AND o.created_at IS NOT NULL            AND o.created_at <= t.created_at            AND o.created_at > t.created_at - make_interval(secs => 3600)       ) END AS creator_prior_mints_1h,        CASE WHEN t.symbol IS NULL OR t.created_at IS NULL THEN NULL ELSE (         SELECT count(*) FROM meme_tokens o WHERE o.symbol = t.symbol            AND o.mint <> t.mint AND o.created_at IS NOT NULL            AND o.created_at <= t.created_at            AND o.created_at > t.created_at - make_interval(secs => 86400)       ) END AS symbol_dup_24h FROM meme_tokens t WHERE t.mint = ANY(ARRAY(SELECT mint FROM meme_features_1m WHERE features_version = 'meme_features_v3' AND end_time = TIMESTAMPTZ '2026-10-01 03:25:00+00'));
